const test = require('node:test');
const assert = require('node:assert/strict');
const { moveUTCMonth } = require('../src/schedule-month.cjs');

test("omitted day keeps the current UTC day and allows rollover", () => {
  const date = new Date('2024-01-31T12:34:56.789Z');
  const result = moveUTCMonth(date, 1);
  assert.equal(date.toISOString(), '2024-03-02T12:34:56.789Z');
  assert.equal(result, date.getTime());
});

test("explicit day and out of range month follow UTC setter rules", () => {
  const date = new Date('2026-08-19T03:20:00.000Z');
  assert.equal(moveUTCMonth(date, 1, 10), Date.parse('2026-02-10T03:20:00.000Z'));
  assert.equal(date.toISOString(), '2026-02-10T03:20:00.000Z');
  moveUTCMonth(date, 15);
  assert.equal(date.toISOString(), '2027-04-10T03:20:00.000Z');
});

test("explicit undefined differs from an omitted day", () => {
  const date = new Date('2026-08-19T03:20:00.000Z');
  assert.equal(Number.isNaN(moveUTCMonth(date, 1, undefined)), true);
  assert.equal(Number.isNaN(date.getTime()), true);
});

